@startuml

class SensorController {
}

class Apartment {
  + address : string
  + email : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

class Sensor {
  + vendor_id : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class SensorType {}

class TemperatureSensor extends SensorType {
  + min : float
  + max : float
}

class PowerSensor extends SensorType {
  + counter_reading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {}

SensorController "1" -- "*" Apartment : manages
Apartment "1" -- "2..*" Room : consists of
Apartment "1" -- "*" Inhabitant : has
Inhabitant "0..*" -- "0..*" Sensor : configures
Sensor "*" -- "1" Room : assigned to
Sensor "1" *-- "*" MeasuredValue : records
SensorController "1" -- "*" Sensor : manages
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "0..1" Apartment : sends alerts to

@enduml

